Ext._define('rh.profile.JobProfileGrid', {
    extend: 'core.RestfulGrid',

    restWindow: 'rh.profile.JobProfileWindow',

    configOrderToolBar: ['add', 'edit', 'remove', '-', 'syncGrants', '-', 'search', '->', 'download'],

    getSyncGrantsAction: function(cfg) {
        if(!this._syncGrantsAction)
            this._syncGrantsAction = Ext._create('Ext.Button', {
                text: 'Sincronizar',
                iconCls: 'icon-core icon-core-add-selected',
                scope: this,
                handler: this.syncGrants
            });

        return this._syncGrantsAction;
    },

    syncGrants: function() {
        var selection = this.getSelectionModel().getSelections();
        var pkset, rest, mask;

        if(selection.length > 0) {
            rest = this.factoryRestful();
            pkset = selection.map(function(data) {
                return data.get('pk');
            });
            mask = new Ext.LoadMask(this.getEl(), {msg: 'Sincronizando permissões...'});

            mask.show();
            rest.doRequest(
                rest.getRoute(
                    'sync_grants',
                    false,
                    'POST',
                    {
                        scope: this,
                        params: {
                            pk__in: pkset
                        },
                        callback: function() {
                            mask.hide();
                            mask = null;
                        },
                        success: function(xhr) {
                            var rst = Ext.decode(xhr.responseText);

                            if(!rst.success)
                                Ext.Msg.show({
                                    title: 'Sincronizando',
                                    icon: Ext.Msg.ERROR,
                                    buttons: Ext.Msg.OK,
                                    msg: rst.message
                                });
                        },
                        failure: function() {
                            Ext.Msg.show({
                                title: 'Sincronizando',
                                icon: Ext.Msg.ERROR,
                                buttons: Ext.Msg.OK,
                                msg: 'Recurso indisponivel no momento.'
                            });
                        }
                    }
                )
            );
        }
        else
            Ext.Msg.show({
                title: 'Sincronizando',
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK,
                msg: 'Primeiro selecione os profiles antes de pedir para sincronizar.'
            });
    },

    rendererOrigin: function(value, cell, data) {
        if(data.get('workplace') !== this.getParams().workplace)
            return value;
        else
            return 'ORIGEM DIRETA';
    },

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: 'Identificador', dataIndex: 'codename', id: 'autoExpandColumn'},
                    {header: 'Origem', dataIndex: 'workplace_unicode', width: 450, renderer: this.rendererOrigin, scope: this},
                    {header: 'Lotação', dataIndex: 'for_workplace', width: 90, renderer: function(value) { return (value ? 'SIM' : 'NÃO'); }},
                    {header: 'Designação', dataIndex: 'for_work_assignment', width: 90, renderer: function(value) { return (value ? 'SIM' : 'NÃO'); }},
                    {header: 'Chefia', dataIndex: 'for_leadership', width: 90, renderer: function(value) { return (value ? 'SIM' : 'NÃO'); }},
                    {header: 'Declaração de atividade', dataIndex: 'for_activity_statement', width: 90, renderer: function(value) { return (value ? 'SIM' : 'NÃO'); }}
                ]
            );

        return this._columnModel;
    }
});

core.RestfulGrid.register(
    'rh.profile.JobProfileRestful',
    'rh.profile.JobProfileGrid'
);

